std::list<std::string> inventory = {"Axe", "Helmet"};

// Task Queue Simulation
inventory.push_front("Initial Task");
inventory.push_back("Cleanup");

// Iterate and remove elements without invalidating other iterators
for (auto it = inventory.begin(); it != inventory.end(); ) {
    if (*it == "Helmet") {
        it = inventory.erase(it); // Erase returns the iterator to the next element
    } else {
        ++it;
    }
}
// Result: {"Initial Task", "Axe", "Cleanup"}

