std::list<int> source = {1, 2, 3};
std::list<int> dest = {99};
auto insertion_point = dest.begin();

// Efficiently move element '2' without copying
auto move_it = source.begin();
std::advance(move_it, 1); // Points to 2

dest.splice(insertion_point, source, move_it);

// source: {1, 3}
// dest: {2, 99}
// splice is O(1)
